Let me draft the test. Existing test file conventions: `describe('given a Slot without a ref', ...)` with `afterEach(cleanup)`.

```tsx
describe('given a Slot without a ref', () => {
  afterEach(cleanup);

  it('should pass the child ref through unchanged (mount, unmount, re-render)', () => {
    const childRef = vi.fn();
    function Wrapper() {
      const [count, setCount] = React.useState(0);
      return (
        <Slot>
          <button type="button" ref={childRef} onClick={() => setCount((c) => c + 1)}>
            {count}
          </button>
        </Slot>
      );
    }
    const { unmount } = render(<Wrapper />);
    const button = screen.getByRole('button');
    // mount: called once with the DOM node
    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenCalledWith(button);
    // re-render: identity of the child's own ref is preserved, no re-attach
    fireEvent.click(button);
    expect(childRef).toHaveBeenCalledTimes(1);
    // unmount: called with null
    unmount();
    expect(childRef).toHaveBeenCalledTimes(2);
    expect(childRef).toHaveBeenLastCalledWith(null);
  });

  it('should keep an object ref attached across re-renders', () => {
    const childRef = React.createRef<HTMLButtonElement>();
    function Wrapper() {
      const [count, setCount] = React.useState(0);
      return (
        <Slot>
          <button type="button" ref={childRef} onClick={() => setCount((c) => c + 1)}>
            {count}
          </button>
        </Slot>
      );
    }
    render(<Wrapper />);
    const button = screen.getByRole('button');
    expect(childRef.current).toBe(button);
    fireEvent.click(button);
    expect(childRef.current).toBe(button);
  });
});
```

